def card(item):
 id=item['id'];picture='image' in item
 out=f'<article class="hh-card" data-hh-item="{id}" id="hh-item-{id}">'
 if picture:out+=f'<figure class="hh-original-picture"><img src="{item["image"]}" width="{item["width"]}" height="{item["height"]}" alt="{escape(item["alt"])}" loading="lazy"></figure><h3>Picture <span class="hh-original-number">{item["number"]}</span></h3>'
 else:out+=f'<h3 class="hh-question"><span class="hh-original-number">{item["number"]}.</span> <span class="hh-original-question" data-glossary>{escape(item["text"])}</span></h3>'+listen(id,'Listen to '+item['label'])
 out+=f'<label class="hh-notes-label" for="hh-notes-{id}">Optional notes · {escape(item["label"])}</label><textarea id="hh-notes-{id}" rows="3" spellcheck="true" placeholder="Optional: note a word or idea, then practise aloud." aria-describedby="hh-feedback-{id}"></textarea><div class="hh-checks">'
 for text in SELF_CHECK['pictures' if picture else 'questions']:out+='<label><input type="checkbox" data-hh-check> <span>'+escape(text)+'</span></label>'
 out+=f'</div><div class="pi-actions"><button type="button" class="btn btn-primary" data-hh-review>Review {escape(item["label"])}</button><button type="button" class="btn btn-secondary" data-hh-reset>Start {escape(item["label"])} again</button><button type="button" class="btn btn-secondary" data-hh-undo hidden>Undo reset {escape(item["label"])}</button></div><p class="hh-feedback" id="hh-feedback-{id}" role="status" aria-live="polite" tabindex="-1" hidden></p></article>'
 return out
